    (60.3, 5.5),
    (76.1, 4.0),
    (76.1, 5.0),
    (88.9, 4.0),
    (88.9, 5.5),
    (88.9, 6.0),
    (101.6, 6.0),
    (114.3, 4.8),
    (114.3, 5.4),
    (114.3, 6.0),
    (139.7, 5.4),
    (165.1, 3.2),
    (168.3, 3.2),
    (168.3, 4.8),
    (168.3, 6.4),
    (219.1, 4.8),
    (219.1, 6.4),
    (273.1, 4.8),
    (273.1, 6.4),
