        def finish_combo(default_name):
            combo = QComboBox()
            for name, hex_value in COLORBOND_CORE_COLOURS.items():
                swatch = QPixmap(24, 24)
                swatch.fill(QColor(hex_value))
                combo.addItem(QIcon(swatch), name)
            combo.setCurrentText(default_name)
            return combo

