    def solve_structure(self, structure):
        if getattr(self, "second_order_checkbox", None) is not None and self.second_order_checkbox.isChecked():
            return structure.solve_second_order()
        d, R, F = structure.solve()
        info = {
            "type": "first_order",
            "converged": True,
            "iterations": 1,
            "first_order_max_abs_mm": max(float(np.max(np.abs(d))), 0.0),
            "second_order_max_abs_mm": max(float(np.max(np.abs(d))), 0.0),
            "displacement_amplification": 1.0,
        }
        return d, R, F, info

    def generate_and_solve_with_popup(self):
        self.generate_and_solve()
        result_text = self.results_box.toPlainText() if hasattr(self, "results_box") else ""
        if result_text.startswith("Input error:") or self.structure is None:
            QMessageBox.critical(self, "Analysis failed", result_text or "The model could not be generated.")

    def recent_preset_settings(self):
        return QSettings("Central Steel Build", APP_DISPLAY_NAME)

    def recent_preset_paths(self):
        settings = self.recent_preset_settings()
        value = settings.value("recentPresetFiles", [])
        if isinstance(value, str):
            paths = [value]
        else:
            paths = list(value or [])
        cleaned = []
        seen = set()
        for path in paths:
            full_path = os.path.abspath(str(path))
            key = os.path.normcase(full_path)
            if key in seen or not os.path.isfile(full_path):
                continue
            cleaned.append(full_path)
            seen.add(key)
            if len(cleaned) >= RECENT_PRESET_LIMIT:
                break
        if cleaned != paths:
            settings.setValue("recentPresetFiles", cleaned)
        return cleaned

    def add_recent_preset_path(self, path):
        if not path:
            return
        full_path = os.path.abspath(str(path))
        key = os.path.normcase(full_path)
        paths = [item for item in self.recent_preset_paths() if os.path.normcase(item) != key]
        paths.insert(0, full_path)
        paths = paths[:RECENT_PRESET_LIMIT]
        self.recent_preset_settings().setValue("recentPresetFiles", paths)
        self.refresh_open_recent_menu()

    def clear_recent_preset_paths(self):
        self.recent_preset_settings().setValue("recentPresetFiles", [])
        self.refresh_open_recent_menu()

    def recent_preset_label(self, path):
        folder = os.path.basename(os.path.dirname(path))
        file_name = os.path.basename(path)
        return f"{file_name} ({folder})" if folder else file_name

    def refresh_open_recent_menu(self):
        menu = getattr(self, "open_recent_menu", None)
        if menu is None:
            return
        menu.clear()
        paths = self.recent_preset_paths()
        if not paths:
            empty_action = QAction("No recent files", self)
            empty_action.setEnabled(False)
            menu.addAction(empty_action)
            return
        for path in paths:
            action = QAction(self.recent_preset_label(path), self)
            action.setToolTip(path)
            action.triggered.connect(lambda checked=False, preset_path=path: self.load_recent_preset(preset_path))
            menu.addAction(action)
        menu.addSeparator()
        clear_action = QAction("&Clear Recent Files", self)
        clear_action.triggered.connect(self.clear_recent_preset_paths)
        menu.addAction(clear_action)

    def write_preset_file(self, path):
        path = str(path)
        if not path.lower().endswith(".json"):
            path += ".json"
        with open(path, "w", encoding="utf-8") as file:
            json.dump(self.collect_preset_data(), file, indent=2)
        self.current_preset_path = path
        self.add_recent_preset_path(path)
        self.mark_model_clean()
        self.update_window_title()
        return path

    def model_snapshot(self):
        if not hasattr(self, "span_input"):
            return None
        return json.dumps(self.collect_preset_data(), sort_keys=True, separators=(",", ":"))

    def model_is_dirty(self):
        if self._clean_model_snapshot is None:
            return False
        return self.model_snapshot() != self._clean_model_snapshot

    def mark_model_clean(self):
        self._clean_model_snapshot = self.model_snapshot()
        self.update_window_title()

    def setup_model_history(self):
        def queue_snapshot(*_):
            QTimer.singleShot(0, self.record_model_snapshot)

        for widget in self.findChildren(QLineEdit):
            widget.editingFinished.connect(queue_snapshot)
        for widget in self.findChildren(QComboBox):
            widget.currentIndexChanged.connect(queue_snapshot)
        for widget in self.findChildren(QCheckBox):
            widget.toggled.connect(queue_snapshot)
        for widget in self.findChildren(QRadioButton):
            widget.toggled.connect(queue_snapshot)
        for widget in self.findChildren(QSpinBox):
            widget.valueChanged.connect(queue_snapshot)
        self.record_model_snapshot()

    def record_model_snapshot(self):
        if self._history_suspended:
            return
        snapshot = self.model_snapshot()
        if snapshot is None or (self._model_history and snapshot == self._model_history[self._model_history_index]):
            self.update_history_actions()
            self.update_window_title()
            return
        del self._model_history[self._model_history_index + 1:]
        self._model_history.append(snapshot)
        self._model_history_index = len(self._model_history) - 1
        self.update_history_actions()
        self.update_window_title()

    def update_history_actions(self):
        if hasattr(self, "undo_action"):
            self.undo_action.setEnabled(self._model_history_index > 0)
            self.redo_action.setEnabled(self._model_history_index + 1 < len(self._model_history))

    def restore_model_history(self, index):
        if index < 0 or index >= len(self._model_history):
            return
        self._history_suspended = True
        try:
            self.apply_preset_data(json.loads(self._model_history[index]))
            self._model_history_index = index
            self.generate_and_solve()
        finally:
            self._history_suspended = False
        self.update_history_actions()
        self.update_window_title()

    def undo_model_change(self):
        self.restore_model_history(self._model_history_index - 1)

    def redo_model_change(self):
        self.restore_model_history(self._model_history_index + 1)

    def new_preset(self):
        if not self.confirm_model_replacement("starting a new model"):
            return
        self.clear_analysis_state()
        self.auto_web_profile_assignments = {}
        self.auto_web_assignment_basis = {}
        self.auto_web_joint_doubler_sides = {}
        self.web_split_failures = {}
        self._last_crane_auto_select_signature = None
        self.current_preset_path = None
        self.update_window_title()
        if not self.load_default_inputs(silent=True):
            data = copy.deepcopy(self.factory_default_data) if self.factory_default_data else None
            if data is not None:
                self.apply_preset_data(data)
            else:
                self.load_factory_defaults(silent=True)
        self.generate_and_solve()
        self._model_history = []
        self._model_history_index = -1
        self.record_model_snapshot()
        self.mark_model_clean()

    def save_preset(self, show_message=True):
        path = self.current_preset_path
        if path:
            try:
                path = self.write_preset_file(path)
            except OSError as exc:
                QMessageBox.critical(self, "Save preset failed", str(exc))
                return False
            if show_message:
                QMessageBox.information(self, "Preset saved", f"Saved preset:\n{path}")
            return True
        return self.save_preset_as(show_message=show_message)

    def save_preset_as(self, show_message=True):
        path, _ = QFileDialog.getSaveFileName(
            self,
            "Save portal frame preset",
            os.path.join(self.default_preset_dir(), "portal_frame_preset.json"),
            "Portal Frame Preset (*.json);;All Files (*)",
        )
        if not path:
            return False
        try:
            path = self.write_preset_file(path)
        except OSError as exc:
            QMessageBox.critical(self, "Save preset failed", str(exc))
            return False
        if show_message:
            QMessageBox.information(self, "Preset saved", f"Saved preset:\n{path}")
        return True

    def load_preset_path(self, path):
        if not self.confirm_model_replacement("opening another model"):
            return False
        try:
            with open(path, "r", encoding="utf-8") as file:
                data = json.load(file)
            self.apply_preset_data(data)
            self.current_preset_path = path
            self.add_recent_preset_path(path)
            self._model_history = []
            self._model_history_index = -1
            self.record_model_snapshot()
            self.mark_model_clean()
            self.update_window_title()
            self.generate_and_solve()
        except (OSError, json.JSONDecodeError, TypeError, ValueError) as exc:
            QMessageBox.critical(self, "Load preset failed", str(exc))
            return False
        return True

    def load_preset(self):
        path, _ = QFileDialog.getOpenFileName(
            self,
            "Load portal frame preset",
            self.default_preset_dir(),
            "Portal Frame Preset (*.json);;All Files (*)",
        )
        if not path:
            return
        self.load_preset_path(path)

    def load_recent_preset(self, path):
        if not os.path.isfile(path):
            QMessageBox.warning(self, "Recent file missing", f"This recent preset could not be found:\n{path}")
            self.refresh_open_recent_menu()
            return
        self.load_preset_path(path)

    def confirm_model_replacement(self, action_text):
        if not self.model_is_dirty():
            return True
        response = QMessageBox.question(
            self,
            "Save current model?",
            f"Do you want to save this preset before {action_text}?",
            QMessageBox.Save | QMessageBox.Discard | QMessageBox.Cancel,
            QMessageBox.Save,
        )
        if response == QMessageBox.Save:
            return self.save_preset(show_message=False)
        return response == QMessageBox.Discard

    def start_configurator_review(self, options: ReviewLaunchOptions):
        """Load and lock a configurator-owned estimate-review session."""

        loaded = load_review_request(options.request_path)
        self.configurator_review = loaded
        self.configurator_review_result_path = options.result_path
        self.configurator_review_finalized = False
        self.configurator_review_auto_optimise_pending = True
        self.configurator_review_optimiser = None
        self.current_preset_path = None
        self.apply_preset_data(copy.deepcopy(dict(loaded.prepared.inputs)))
        self.configure_configurator_review_ui()
        self.generate_and_solve()
        self.update_configurator_review_status(prefix="Optimisation queued on open. ")
        self.mark_model_clean()
        self.update_window_title()

    def configurator_review_member_combos(self):
        names = (
            "left_column_profile_combo",
            "right_column_profile_combo",
            "internal_column_profile_combo",
            "top_profile_combo",
            "web_profile_combo",
            "left_canopy_top_profile_combo",
            "left_canopy_web_profile_combo",
            "left_lean_column_profile_combo",
            "right_canopy_top_profile_combo",
            "right_canopy_web_profile_combo",
            "right_lean_column_profile_combo",
            "end_wall_brace_size_combo",
            "roof_brace_size_combo",
            "wall_brace_size_combo",
            "storage_rail_profile_combo",
            "storage_stub_profile_combo",
            "crane_beam_profile_combo",
            "crane_beam_rail_profile_combo",
        )
        return [getattr(self, name) for name in names if getattr(self, name, None) is not None]

    def configure_configurator_review_ui(self):
        banner = QWidget()
        banner_layout = QVBoxLayout(banner)
        banner_layout.setContentsMargins(10, 8, 10, 8)
        title = QLabel("Estimate review — not engineering approval")
        title.setStyleSheet("font-size: 16px; font-weight: bold;")
        status = QLabel()
        status.setWordWrap(True)
        actions = QHBoxLayout()
        return_button = QPushButton("Return reviewed estimate")
        cancel_button = QPushButton("Cancel")
        return_button.clicked.connect(self.return_configurator_review)
        cancel_button.clicked.connect(self.cancel_configurator_review)
        actions.addWidget(return_button)
        actions.addWidget(cancel_button)
        banner_layout.addWidget(title)
        banner_layout.addWidget(status)
        banner_layout.addLayout(actions)
        self.left_panel_layout.insertWidget(0, banner)
        self.configurator_review_banner = banner
        self.configurator_review_title_label = title
        self.configurator_review_status_label = status
        self.configurator_review_return_button = return_button
        self.configurator_review_cancel_button = cancel_button

        allowed_combos = set(self.configurator_review_member_combos())
        allowed_combos.add(self.depth_input)
        display_controls = {
            getattr(self, name, None)
            for name in ("result_combo", "load_view_mode_combo", "single_load_combo")
        }
        allowed_combos.update(item for item in display_controls if item is not None)
        allowed_buttons = {return_button, cancel_button, self.optimise_structure_button}
        allowed_selector_parents = {combo.parentWidget() for combo in allowed_combos}

        for widget in self.findChildren(QWidget):
            if isinstance(widget, (QLineEdit, QComboBox, QCheckBox, QSpinBox, QRadioButton)):
                widget.setEnabled(widget in allowed_combos)
        for button in self.findChildren(QPushButton):
            button.setEnabled(button in allowed_buttons)
        for button in self.findChildren(QToolButton):
            button.setEnabled(button.parentWidget() in allowed_selector_parents)

        self.sections_guided_optimise_button.setEnabled(False)
        self.sections_ai_help_button.setEnabled(False)
        try:
            self.optimise_structure_button.clicked.disconnect()
        except (RuntimeError, TypeError):
            pass
        self.optimise_structure_button.clicked.connect(self.run_configurator_review_optimisation)
        self.depth_input.editingFinished.connect(self.on_configurator_review_depth_edited)
        self.optimise_structure_button.setText("Optimise members for estimate")
        self.optimise_structure_button.setToolTip(
            "Run PortalCalc optimisation, retain its member selections, restore all configurator-owned inputs, "
            "then solve the restored configuration exactly."
        )
        for action in self.menuBar().actions():
            if "Help" not in action.text():
                action.setEnabled(False)
        self.input_tabs.setCurrentWidget(self.sections_tab)
        banner.setStyleSheet("background:#f6c453; color:#18222d; border:2px solid #9b6a00;")

    def _configurator_review_web_state(self):
        return {
            "assignments": copy.deepcopy(self.auto_web_profile_assignments),
            "doubler_sides": copy.deepcopy(self.auto_web_joint_doubler_sides),
        }

    def configurator_review_depth_validation(self):
        try:
            depth_mm = validate_review_truss_depth(
                self.configurator_review.prepared.inputs,
                self.depth_input.text(),
            )
            minimum_mm, maximum_mm = review_truss_depth_bounds(
                self.configurator_review.prepared.inputs
            )
            return depth_mm, minimum_mm, maximum_mm, None
        except ValueError as exc:
            return None, None, None, str(exc)

    def on_configurator_review_depth_edited(self):
        if self.configurator_review is None:
            return
        _, _, _, error = self.configurator_review_depth_validation()
        if error:
            self.configurator_review_status_label.setText(f"DEPTH ERROR: {error}. Return is blocked.")
            self.configurator_review_status_label.setStyleSheet(
                "font-weight:bold; color:white; background:#8f1d1d; padding:6px;"
            )
            return
        current_inputs = self.collect_preset_data()
        review_inputs = merge_reviewable_selections(
            self.configurator_review.prepared.inputs,
            current_inputs,
        )
        web_state = self._configurator_review_web_state()
        review_inputs["calculation_service"] = calculation_json_safe({
            "auto_web_profile_assignments": copy.deepcopy(web_state["assignments"]),
            "auto_web_joint_doubler_sides": copy.deepcopy(web_state["doubler_sides"]),
        })
        self._solve_configurator_review_inputs(review_inputs)
        self.update_configurator_review_status(prefix="Depth updated. ")

    def _solve_configurator_review_inputs(self, inputs, web_state=None):
        self.apply_preset_data(copy.deepcopy(dict(inputs)))
        request_web_state = calculation_web_selection_state(inputs)
        request_assignments = request_web_state["assignments"]
        assignments = copy.deepcopy(
            (web_state or {}).get("assignments") or request_assignments
        )
        if assignments:
            self.auto_web_profile_assignments = assignments
            self.auto_web_joint_doubler_sides = copy.deepcopy(
                (web_state or {}).get("doubler_sides")
                or request_web_state["doubler_sides"]
                or {}
            )
            self.auto_web_assignment_basis = {
                group: self.web_assignment_basis_signature(group) for group in assignments
            }
        previous_preserve = getattr(self, "_preserve_web_assignments_on_solve", False)
        self._preserve_web_assignments_on_solve = bool(assignments)
        try:
            self.generate_and_solve()
        finally:
            self._preserve_web_assignments_on_solve = previous_preserve

    def run_configurator_review_optimisation(self):
        if self.configurator_review is None:
            return
        self.configurator_review_auto_optimise_pending = False
        physics_result = self.run_physics_structure_optimisation(show_completion=False)
        self.configurator_review_optimiser = "physics"
        optimised_inputs = self.collect_preset_data()
        web_state = self._configurator_review_web_state()
        review_inputs = merge_reviewable_selections(
            self.configurator_review.prepared.inputs,
            optimised_inputs,
        )
        review_inputs["calculation_service"] = calculation_json_safe({
            "auto_web_profile_assignments": copy.deepcopy(web_state["assignments"]),
            "auto_web_joint_doubler_sides": copy.deepcopy(web_state["doubler_sides"]),
        })
        self._solve_configurator_review_inputs(review_inputs)
        self.optimise_structure_button.setText("Optimise members for estimate")
        verified = isinstance(physics_result, dict) and physics_result.get("verified") is True
        self.update_configurator_review_status(prefix=(
            "Physics Optimise complete. " if verified
            else "Physics Optimise found no verified candidate. Review the exact checks. "
        ))

    def start_pending_configurator_review_optimisation(self):
        if (
            self.configurator_review is None
            or self.configurator_review_finalized
            or not self.configurator_review_auto_optimise_pending
        ):
            return False
        self.configurator_review_auto_optimise_pending = False
        self.run_configurator_review_optimisation()
        return True

    def update_configurator_review_status(self, prefix=""):
        if self.configurator_review_status_label is None:
            return
        _, minimum_mm, maximum_mm, depth_error = self.configurator_review_depth_validation()
        if depth_error:
            self.configurator_review_status_label.setText(
                f"DEPTH ERROR: {depth_error}. Return reviewed estimate is blocked."
            )
            self.configurator_review_status_label.setStyleSheet(
                "font-weight:bold; color:white; background:#8f1d1d; padding:6px;"
            )
            return
        if self.structure is None or self.design_envelope_actions is None:
            message = "FAILED OR UNCHECKED — PortalCalc did not produce a solved model."
            colour = "#8f1d1d"
        else:
            active_specs = self.active_auto_size_group_specs()
            ratio, group, check = self.auto_size_overall_ratio(active_specs)
            verified = self.auto_size_design_acceptable(active_specs, ratio)
            if verified:
                message = (
                    f"Current exact check passes: {group} / {check}, ratio {ratio:.3f}. "
                    f"Truss depth range {minimum_mm:.0f}–{maximum_mm:.0f} mm."
                )
                colour = "#176b3a"
            else:
                message = (
                    f"FAILED OR UNCHECKED: {group} / {check}, ratio {ratio:.3f}. "
                    f"Truss depth range {minimum_mm:.0f}–{maximum_mm:.0f} mm. "
                    "It may still be returned for estimating."
                )
                colour = "#8f1d1d"
        self.configurator_review_status_label.setText(prefix + message)
        self.configurator_review_status_label.setStyleSheet(
            f"font-weight:bold; color:white; background:{colour}; padding:6px;"
        )

    def configurator_review_selected_sections(self, inputs, dossier):
        selected = {
            "presetSelections": copy.deepcopy((inputs or {}).get("sections", {})),
            "automaticWebAssignments": copy.deepcopy(self.auto_web_profile_assignments),
        }
        for label, check in (
            ("purlin", self.purlin_check),
            ("wallGirt", self.wall_girt_check),
            ("endWallGirt", self.end_wall_girt_check),
        ):
            if isinstance(check, dict):
                selected[label] = {
                    "general": (check.get("match") or {}).get("section"),
                    "local": (check.get("local_match") or {}).get("section"),
                }
        if isinstance(self.storage_rail_design, dict):
            profile = self.storage_rail_design.get("profile")
            selected["storageRail"] = getattr(profile, "name", str(profile) if profile else None)
        crane = self.current_crane_beam_summary()
        if crane:
            selected["craneRunwayBeam"] = crane.get("section")
        end_wall = self.end_wall_mullion_design or {}
        if isinstance(end_wall, dict):
            selected["endWallMullion"] = end_wall.get("section") or end_wall.get("selected_section")
        selected["doubledChordZones"] = copy.deepcopy(
            (self.design_envelope_actions or {}).get("doubled_chord_zones", [])
        )
        return calculation_json_safe(selected)

    def _configurator_review_dossier(self, final_inputs):
        if self.structure is not None and self.design_envelope_actions is not None:
            dossier = self.assistant_design_dossier()
            dossier["inputs"] = copy.deepcopy(final_inputs)
        else:
            detail = self.results_box.toPlainText().strip() or "PortalCalc did not produce a solved model"
            dossier = {
                "schema": "portalcalc.calculation.dossier.v1",
                "portalcalc_version": APP_VERSION,
                "status": "failed or unchecked",
                "inputs": copy.deepcopy(final_inputs),
                "analysis": {"status": "not solved", "error": detail},
                "overall_governing": {
                    "ratio": "infinity",
                    "group": "UNRESOLVED",
                    "check": detail,
                    "passes_ratio_screen": False,
                },
                "member_checks": [],
                "serviceability_checks": [],
            }
        dossier["warnings"] = [
            "Estimate review only — not engineering approval or construction release.",
        ]
        dossier["engine_provenance"] = {
            "runtime": "interactive Configurator Review exact checkSpecified",
            "estimate_optimiser": getattr(self, "configurator_review_optimiser", None),
            **calculation_source_provenance(),
        }
        return dossier

    def return_configurator_review(self, *, show_message=True, close_after=True):
        if self.configurator_review is None or self.configurator_review_finalized:
            return None
        depth_mm, _, maximum_mm, depth_error = self.configurator_review_depth_validation()
        if depth_error:
            self.update_configurator_review_status()
            if show_message:
                QMessageBox.warning(
                    self,
                    "Invalid truss depth",
                    f"{depth_error}. Enter a valid 50 mm increment before returning the estimate.",
                )
            return None
        self.configurator_review_return_button.setEnabled(False)
        QApplication.processEvents()
        try:
            current_inputs = self.collect_preset_data()
            final_inputs = merge_reviewable_selections(
                self.configurator_review.prepared.inputs,
                current_inputs,
            )
            web_state = self._configurator_review_web_state()
            final_inputs["calculation_service"] = calculation_json_safe({
                "auto_web_profile_assignments": copy.deepcopy(web_state["assignments"]),
                "auto_web_joint_doubler_sides": copy.deepcopy(web_state["doubler_sides"]),
            })
            final_raw = {
                "schema": self.configurator_review.prepared.schema,
                "request_id": self.configurator_review.prepared.request_id,
                "mode": CalculationMode.CHECK_SPECIFIED.value,
                "inputs": final_inputs,
            }
            prepared_final = prepare_calculation_request(final_raw)
            self._solve_configurator_review_inputs(prepared_final.inputs)
            dossier = self._configurator_review_dossier(prepared_final.inputs)

            class FrozenReviewBackend:
                def calculate(inner_self, request):
                    return copy.deepcopy(dossier)

            service_result = PortalCalcCalculationService(FrozenReviewBackend()).run(final_raw)
            selected = self.configurator_review_selected_sections(prepared_final.inputs, dossier)
            reviewed_result = build_reviewed_result(
                service_result,
                original_request_digest=self.configurator_review.prepared.input_digest,
                final_input_digest=prepared_final.input_digest,
                selected_sections=selected,
                selected_geometry={
                    "trussDepthMm": depth_mm,
                    "maxTrussDepthMm": maximum_mm,
                },
            )
            atomic_write_json(self.configurator_review_result_path, reviewed_result)
            self.configurator_review_finalized = True
            self.update_configurator_review_status(prefix="Returned. ")
            verified = bool(reviewed_result.get("verified"))
            if show_message:
                message = (
                    f"Reviewed estimate written to:\n{self.configurator_review_result_path}\n\n"
                    + ("The final exact check passes." if verified else "FAILED OR UNCHECKED — the result was returned for estimating only.")
                )
                if verified:
                    QMessageBox.information(self, "Estimate review returned", message)
                else:
                    QMessageBox.warning(self, "Failed or unchecked estimate returned", message)
            if close_after:
                self.confirm_on_close = False
                self.close()
            return reviewed_result
        except Exception as exc:
            self.configurator_review_return_button.setEnabled(True)
            self.configurator_review_status_label.setText(f"RETURN FAILED: {exc}")
            self.configurator_review_status_label.setStyleSheet(
                "font-weight:bold; color:white; background:#8f1d1d; padding:6px;"
            )
            if show_message:
                QMessageBox.critical(self, "Could not return reviewed estimate", str(exc))
            return None

    def cancel_configurator_review(self, *, show_message=False, close_after=True):
        if self.configurator_review is None or self.configurator_review_finalized:
            return None
        cancelled = build_cancelled_result(self.configurator_review)
        try:
            atomic_write_json(self.configurator_review_result_path, cancelled)
        except OSError as exc:
            if show_message:
                QMessageBox.critical(self, "Could not cancel estimate review", str(exc))
            return None
        self.configurator_review_finalized = True
        if close_after:
            self.confirm_on_close = False
            self.close()
        return cancelled

    def closeEvent(self, event):
        assistant_thread = getattr(self, "assistant_request_thread", None)
        help_thread = getattr(self, "assistant_help_request_thread", None)
        optimise_thread = getattr(self, "assistant_optimise_request_thread", None)
        if (
            assistant_thread is not None and assistant_thread.isRunning()
        ) or (
            help_thread is not None and help_thread.isRunning()
        ) or (
            optimise_thread is not None and optimise_thread.isRunning()
        ) or getattr(self, "assistant_help_session", None) is not None or getattr(
            self, "assistant_optimise_session", None
        ) is not None:
            QMessageBox.information(
                self,
                "Structural Assistant",
                "Wait for the current assistant or guided optimisation workflow to finish before closing PortalCalc.",
            )
            event.ignore()
            return
        if self.configurator_review is not None and not self.configurator_review_finalized:
            response = QMessageBox.question(
                self,
                "Cancel estimate review?",
                "Close PortalCalc and return a cancelled result without a reviewed estimate?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if response == QMessageBox.Yes:
                cancelled = self.cancel_configurator_review(close_after=False)
                if cancelled is not None:
                    event.accept()
                else:
                    event.ignore()
            else:
                event.ignore()
            return
        if not getattr(self, "confirm_on_close", True):
            event.accept()
            return
        if self.confirm_model_replacement("closing"):
            event.accept()
        else:
            event.ignore()

    def save_default_inputs(self):
        path = self.default_settings_path()
        try:
            with open(path, "w", encoding="utf-8") as file:
                json.dump(self.collect_preset_data(), file, indent=2)
        except OSError as exc:
            QMessageBox.critical(self, "Save defaults failed", str(exc))
            return
        QMessageBox.information(self, "Defaults saved", f"Saved default inputs:\n{path}")

    def load_default_inputs(self, silent=False):
        path = self.default_settings_path()
        if not os.path.exists(path):
            return False
        try:
            with open(path, "r", encoding="utf-8") as file:
                data = json.load(file)
            self.apply_preset_data(data)
        except (OSError, json.JSONDecodeError, TypeError, ValueError) as exc:
            if not silent:
                QMessageBox.critical(self, "Load defaults failed", str(exc))
            return False
        return True

    def reset_default_inputs(self):
        if self.factory_default_data:
            self.apply_preset_data(self.factory_default_data)
            self.generate_and_solve()
        path = self.default_settings_path()
        try:
            if os.path.exists(path):
                os.remove(path)
        except OSError as exc:
            QMessageBox.critical(self, "Reset defaults failed", str(exc))
            return
        QMessageBox.information(self, "Defaults reset", "Default inputs have been reset to the factory defaults.")

    def concept_3d_data(self):
        return concept_3d.concept_3d_data(self)
    def concept_3d_html(self, data):
        return concept_3d.concept_3d_html(self, data)
    def concept_3d_dae(self, data, return_mesh=False):
        return concept_3d.concept_3d_dae(self, data, return_mesh=return_mesh)
    def export_3d_concept(self):
        return concept_3d.export_3d_concept(self)
    def export_elevation_sheet(self):
        try:
            data = self.concept_3d_data()
        except (TypeError, ValueError) as exc:
            QMessageBox.warning(self, "Drawing set export", str(exc).replace("3D concept", "drawing set"))
            return
        preset_name = os.path.splitext(os.path.basename(self.current_preset_path or "Portal Frame"))[0]
        path, _ = QFileDialog.getSaveFileName(
            self,
            "Export drawing set",
            os.path.join(os.getcwd(), f"{preset_name} - Drawing Set.pdf"),
            "PDF files (*.pdf);;All files (*.*)",
        )
        if not path:
            return
        metadata = {
            "project": preset_name.upper(),
            "description": "PORTAL FRAME",
            "job_number": preset_name.upper(),
            "revision": "A",
        }
        try:
            path = export_elevation_pdf(data, path, metadata)
        except (OSError, TypeError, ValueError) as exc:
            QMessageBox.critical(self, "Drawing set export failed", str(exc))
            return
        if not QDesktopServices.openUrl(QUrl.fromLocalFile(path)):
            QMessageBox.information(self, "Drawing set exported", f"Exported, but could not open the PDF viewer:\n{path}")

    def apply_base_support(self, structure, node, support_type, spring_k_nmm_per_rad=0.0):
        structure.add_support(node.ux)
        structure.add_support(node.uy)
        if support_type == "Fixed":
            structure.add_support(node.rz)
        elif support_type == "Spring":
            structure.add_spring(node.rz, spring_k_nmm_per_rad)

    def column_cladding_restraints(self, frame_type):
        if hasattr(frame_type, "left_wall_clad") and hasattr(frame_type, "right_wall_clad"):
            return {
                "LEFT_COLUMN": bool(frame_type.left_wall_clad),
                "RIGHT_COLUMN": bool(frame_type.right_wall_clad),
            }
        if frame_type == "Enclosed":
            return {"LEFT_COLUMN": True, "RIGHT_COLUMN": True}
        if frame_type in {"3 Sided", "2 Sided", "1 Sided"}:
            return {"LEFT_COLUMN": True, "RIGHT_COLUMN": False}
        return {"LEFT_COLUMN": False, "RIGHT_COLUMN": False}

    def purlin_mid_span_limit_mm(self, wind_region, importance_level):
        if str(wind_region).upper() == "C":
            return 1100.0
        if int(importance_level) >= 2:
            return 1600.0
        return 1700.0

    def wall_girt_spacing_mm(self, wind_region):
        if str(wind_region).upper() == "C":
            return 1100.0
        return 1700.0

    def bridging_label_text(self, label):
        text = str(label or "-").strip()
        match = re.search(r"B(\d+)", text.upper())
        if match:
            rows = int(match.group(1))
            suffix = "row" if rows == 1 else "rows"
            extra = " / side bridging" if "SB" in text.upper() else ""
            return f"{text} ({rows} {suffix}{extra})"
        return text

    def bridging_row_count(self, label):
        match = re.search(r"B(\d+)", str(label or "").upper())
        return int(match.group(1)) if match else 0

    def purlin_depth_from_section(self, section):
        numbers = [float(value) for value in re.findall(r"\d+", section or "")]
        return numbers[0] if numbers else 0.0

    @staticmethod
    def metroll_section_display(section, span_type):
        """Display C sections for simple spans and Z sections for lapped spans."""
        text = str(section or "").strip()
        if not text:
            return text
        prefix = "Z" if str(span_type or "") == "Continuous lapped" else "C"
        return re.sub(r"^(?:C\s*/\s*Z|C|Z)\s*", f"{prefix} ", text, flags=re.IGNORECASE).strip()

    def recommended_purlin_bridging_spacing_mm(self, section):
        depth = self.purlin_depth_from_section(section)
        if depth <= 0.0:
            return 0.0
        return 3000.0 if depth <= 150.0 else 4000.0

    def minimum_purlin_bridging_rows(self, section, span_mm):
        max_spacing = self.recommended_purlin_bridging_spacing_mm(section)
        if max_spacing <= 0.0 or span_mm <= 0.0:
            return 0
        return max(0, math.ceil(span_mm / max_spacing) - 1)

    def bridged_strength_capacity(self, row, section, span_mm, demand_kn_m):
        values = row.get("strength_by_bridging_kn_m") or {}
        if not values:
            label = row.get("strength_bridging", "-")
            capacity = row.get("strength_capacity_kn_m", 0.0)
            rows = self.bridging_row_count(label)
            max_spacing = self.recommended_purlin_bridging_spacing_mm(section)
            return {
                "capacity": capacity,
                "label": label,
                "rows": rows,
                "minimum_rows": self.minimum_purlin_bridging_rows(section, span_mm),
                "max_spacing_mm": max_spacing,
                "max_bay_mm": max_spacing * (rows + 1) if max_spacing > 0.0 else 0.0,
            }
        minimum_rows = self.minimum_purlin_bridging_rows(section, span_mm)
        options = [
            (self.bridging_row_count(label), label, capacity)
            for label, capacity in values.items()
            if self.bridging_row_count(label) >= minimum_rows
        ]
        if not options:
            options = [
                (self.bridging_row_count(label), label, capacity)
                for label, capacity in values.items()
            ]
        options.sort(key=lambda item: (item[0], item[1]))
        passing = [item for item in options if demand_kn_m <= item[2] + 1e-9]
        rows, label, capacity = passing[0] if passing else max(options, key=lambda item: item[2])
        max_spacing = self.recommended_purlin_bridging_spacing_mm(section)
        return {
            "capacity": capacity,
            "label": label,
            "rows": rows,
            "minimum_rows": minimum_rows,
            "max_spacing_mm": max_spacing,
            "max_bay_mm": max_spacing * (rows + 1) if max_spacing > 0.0 else 0.0,
        }

    def actual_wall_girt_spacing_mm(self, eave_height_mm, wind_region, bottom_girt_height_mm=300.0):
        max_spacing = self.wall_girt_spacing_mm(wind_region)
        if eave_height_mm <= 0.0:
            return max_spacing
        if eave_height_mm <= bottom_girt_height_mm + 1e-9:
            return eave_height_mm
        clad_height_mm = max(eave_height_mm - bottom_girt_height_mm, 0.0)
        spaces = max(1, math.ceil(clad_height_mm / max_spacing))
        return clad_height_mm / spaces

    def profile_depth_mm(self, profile):
        if getattr(profile, "depth", 0.0) and profile.depth > 0.0:
            return profile.depth
        match = re.search(r"(\d+(?:\.\d+)?)", profile.name)
        return float(match.group(1)) if match else 0.0

    def adjust_extra_purlin_rows(self, delta):
        self.extra_purlin_rows = max(0, int(getattr(self, "extra_purlin_rows", 0)) + int(delta))
        self.update_extra_purlin_rows_label()
        self.generate_and_solve()

    def update_extra_purlin_rows_label(self):
        if not getattr(self, "extra_purlin_rows_label", None):
            return
        rows = int(getattr(self, "extra_purlin_rows", 0))
        self.extra_purlin_rows_label.setText(f"Manual extra roof purlin rows per slope: {rows}")
        if getattr(self, "remove_purlin_row_button", None):
            self.remove_purlin_row_button.setEnabled(rows > 0)

    def purlin_bridging_summary_text(self, purlin_check):
        if not purlin_check:
            return "Not checked"
        match = purlin_check.get("match", {}) or {}
        local_match = purlin_check.get("local_match", {}) or {}
        span_type = purlin_check.get("span_type", "")
        if match.get("status") != "OK" and local_match.get("status") != "OK":
            return "No passing Metroll section selected"
        def bridge_suffix(item):
            rows = int(item.get("bridging_rows", 0) or 0)
            return f"({rows}-row)"
        def part(item):
            if item.get("status") != "OK":
                return "Not passing"
            return f"{self.metroll_section_display(item.get('section', '-'), span_type)} {bridge_suffix(item)}"
        if local_match.get("status") == "OK" and (
            local_match.get("section") != match.get("section")
            or int(local_match.get("bridging_rows", 0) or 0) != int(match.get("bridging_rows", 0) or 0)
        ):
            edge_rows = int(purlin_check.get("edge_rows", 0) or 0)
            return (
                f"{part(match)}; first {edge_rows} edge rows "
                f"{self.metroll_section_display(local_match.get('section', '-'), span_type)} "
                f"{bridge_suffix(local_match)}"
            )
        return part(match if match.get("status") == "OK" else local_match)

    def build_purlin_layout(self, top_nodes, wind_region, importance_level):
        end_limit = 1200.0
        mid_limit = self.purlin_mid_span_limit_mm(wind_region, importance_level)
        if len(top_nodes) < 2:
            return PurlinLayout([], mid_limit, end_limit, mid_limit)

        points = []
        spacings = []

        def point_at_distance(nodes, distance):
            remaining = distance
            for n1, n2 in zip(nodes[:-1], nodes[1:]):
                dx = n2.x - n1.x
                dy = n2.y - n1.y
                length = math.hypot(dx, dy)
                if length <= 1e-9:
                    continue
                if remaining <= length:
                    t = remaining / length
                    return (n1.x + dx * t, n1.y + dy * t)
                remaining -= length
            return (nodes[-1].x, nodes[-1].y)

        def slope_points(nodes):
            lengths = [math.hypot(n2.x - n1.x, n2.y - n1.y) for n1, n2 in zip(nodes[:-1], nodes[1:])]
            slope_length = sum(lengths)
            if slope_length <= 1e-9:
                return []
            extra_rows = int(getattr(self, "extra_purlin_rows", 0))
            if slope_length <= 2.0 * end_limit:
                spaces = max(1, extra_rows + 1)
                stations = [slope_length * i / spaces for i in range(spaces + 1)]
            else:
                middle_length = slope_length - 2.0 * end_limit
                middle_spaces = max(1, math.ceil(middle_length / mid_limit) + extra_rows)
                actual_mid_spacing = middle_length / middle_spaces
                stations = [0.0, end_limit]
                stations.extend(end_limit + actual_mid_spacing * i for i in range(1, middle_spaces))
                stations.extend([slope_length - end_limit, slope_length])
            return [(station, point_at_distance(nodes, station)) for station in sorted(set(round(s, 6) for s in stations))]

        for slope in self.roof_slope_node_sets(top_nodes):
            slope_layout = slope_points(slope)
            points.extend(point for _, point in slope_layout)
            spacings.extend(b - a for (a, _), (b, _) in zip(slope_layout[:-1], slope_layout[1:]))

        unique_points = []
        seen = set()
        for x, y in points:
            key = (round(x, 3), round(y, 3))
            if key not in seen:
                seen.add(key)
                unique_points.append((x, y))

        return PurlinLayout(unique_points, max(spacings or [mid_limit]), end_limit, mid_limit)

    def current_roof_shape(self):
        if getattr(self, "roof_shape_combo", None) is None:
            return "Gable"
        return self.roof_shape_combo.currentText() or "Gable"

    def roof_slope_node_sets(self, top_nodes, roof_shape=None):
        if len(top_nodes) < 2:
            return []
        roof_shape = roof_shape or self.current_roof_shape()
        if roof_shape == "Skillion":
            return [top_nodes]
        apex_index = max(range(len(top_nodes)), key=lambda i: top_nodes[i].y)
        slopes = [top_nodes[:apex_index + 1], list(reversed(top_nodes[apex_index:]))]
        return [nodes for nodes in slopes if len(nodes) >= 2]

    def member_check_restraint_lengths(
        self,
        frame_type,
        left_base,
        right_base,
        bottom_nodes,
        purlin_layout=None,
        column_top_deduction_mm=0.0,
        crane_minor_height_mm=None,
        clad_column_heights_mm=None,
        storage_restraint_levels_mm=None,
    ):
        cladding = self.column_cladding_restraints(frame_type)
        clad_column_heights_mm = clad_column_heights_mm or {}
        storage_restraint_levels_mm = storage_restraint_levels_mm or {}
        column_top_deduction_mm = max(column_top_deduction_mm, 0.0)
        left_unclad_length = max(abs(bottom_nodes[0].y - left_base.y) - column_top_deduction_mm, 0.0)
        right_unclad_length = max(abs(bottom_nodes[-1].y - right_base.y) - column_top_deduction_mm, 0.0)
        top_chord_minor_length = purlin_layout.max_spacing_mm if purlin_layout is not None else 1700.0
        bottom_chord_minor_length = 2.0 * top_chord_minor_length
        flybraced_length = 2.0 * top_chord_minor_length

        crane_minor_height_mm = crane_minor_height_mm if crane_minor_height_mm and crane_minor_height_mm > 0.0 else None

        def column_lengths(group, unclad_length, base_y, top_y):
            if cladding[group]:
                clad_height_mm = max(float(clad_column_heights_mm.get(group, 0.0) or 0.0), abs(top_y - base_y))
                flybraced_column_length = max(clad_height_mm / 2.0, 0.0)
                major_length = flybraced_column_length
                minor_length = flybraced_column_length
                clad = True
            else:
                major_length = unclad_length
                minor_length = unclad_length
                clad = False
            restraint_levels = sorted(
                level for level in storage_restraint_levels_mm.get(group, [])
                if min(base_y, top_y) + 1e-6 < level < max(base_y, top_y) - 1e-6
            )
            if restraint_levels:
                stations = [base_y] + restraint_levels + [top_y]
                storage_segment_length = max(abs(y2 - y1) for y1, y2 in zip(stations[:-1], stations[1:]))
                major_length = min(major_length, storage_segment_length) if major_length > 0.0 else storage_segment_length
                minor_length = min(minor_length, storage_segment_length) if minor_length > 0.0 else storage_segment_length
            if crane_minor_height_mm is not None and group in {"LEFT_COLUMN", "RIGHT_COLUMN"}:
                minor_length = min(minor_length, crane_minor_height_mm) if minor_length > 0.0 else crane_minor_height_mm
            return {
                "major_mm": major_length,
                "minor_mm": minor_length,
                "ke": 0.85,
                "am": 1.75,
                "kt": 1.0,
                "kl": 1.0,
                "kr": 1.0,
                "clad": clad,
                "crane_minor": crane_minor_height_mm is not None and group in {"LEFT_COLUMN", "RIGHT_COLUMN"},
                "storage_restraint": bool(restraint_levels),
            }

        restraints = {
            "LEFT_COLUMN": column_lengths("LEFT_COLUMN", left_unclad_length, left_base.y, bottom_nodes[0].y),
            "RIGHT_COLUMN": column_lengths("RIGHT_COLUMN", right_unclad_length, right_base.y, bottom_nodes[-1].y),
            "WEB": {"major_mm": None, "minor_mm": None, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": None},
            "LEFT_CANOPY_WEB": {"major_mm": None, "minor_mm": None, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": None},
            "RIGHT_CANOPY_WEB": {"major_mm": None, "minor_mm": None, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": None},
            "TOP": {"major_mm": None, "minor_mm": top_chord_minor_length, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": None},
            "BOTTOM": {"major_mm": None, "minor_mm": bottom_chord_minor_length, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": None},
            "LEFT_CANOPY_TOP": {"major_mm": None, "minor_mm": top_chord_minor_length, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": None},
            "LEFT_CANOPY_BOTTOM": {"major_mm": None, "minor_mm": top_chord_minor_length, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": None},
            "RIGHT_CANOPY_TOP": {"major_mm": None, "minor_mm": top_chord_minor_length, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": None},
            "RIGHT_CANOPY_BOTTOM": {"major_mm": None, "minor_mm": top_chord_minor_length, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": None},
            "LEFT_LEAN_COLUMN": {"major_mm": None, "minor_mm": None, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": False},
            "RIGHT_LEAN_COLUMN": {"major_mm": None, "minor_mm": None, "ke": 1.0, "am": 1.0, "kt": 1.0, "kl": 1.0, "kr": 1.0, "clad": False},
        }
        if getattr(self, "left_canopy_frame_system_combo", None) is not None and self.canopy_side_is_rafter("left"):
            restraints["LEFT_CANOPY_TOP"].update({"major_mm": flybraced_length, "minor_mm": top_chord_minor_length})
        if getattr(self, "right_canopy_frame_system_combo", None) is not None and self.canopy_side_is_rafter("right"):
            restraints["RIGHT_CANOPY_TOP"].update({"major_mm": flybraced_length, "minor_mm": top_chord_minor_length})
        return restraints

    def selected_end_wall_brace_size(self):
        return self.selected_brace_size(self.end_wall_brace_size_combo)

    def selected_brace_size(self, combo):
        data = combo.currentData()
        if isinstance(data, dict):
            return {
                "label": data.get("label", combo.currentText()),
                "area_mm2": float(data.get("area_mm2", 0.0)),
                "description": data.get("description", combo.currentText()),
            }
        label = combo.currentText()
        for option_label, area_mm2, description in END_WALL_BRACING_SIZE_OPTIONS:
            if option_label == label:
                return {"label": option_label, "area_mm2": area_mm2, "description": description}
        return {"label": "16 DIA ROD", "area_mm2": math.pi * 16.0**2 / 4.0, "description": "16 mm round bar"}

    def end_wall_bracing_eave_spring(self, building_length_m, bay_size_m, brace_area_mm2, end_count=1, brace_label="Brace"):
        bay_size_m = max(bay_size_m, 1e-9)
        building_length_m = max(building_length_m, 0.0)
        bay_size_mm = bay_size_m * 1000.0
        brace_area_mm2 = max(brace_area_mm2, 0.0)
        end_count = 2 if end_count >= 2 else 1
        diagonal_length_mm = math.sqrt(2.0) * bay_size_mm
        base_spring_kn_mm = (200000.0 * brace_area_mm2 / diagonal_length_mm) * 0.5 / 1000.0
        calibrated_base_spring_kn_mm = base_spring_kn_mm * EAVE_BRACING_PATH_CALIBRATION_FACTOR

        path_m = building_length_m / 2.0
        squares_to_end = max(1, math.ceil(path_m / bay_size_m))
        one_end_spring_kn_mm = calibrated_base_spring_kn_mm / squares_to_end
        effective_spring_kn_mm = one_end_spring_kn_mm * end_count

        return {
            "modelled": True,
            "end_count": end_count,
            "squares_to_end": squares_to_end,
            "path_m": path_m,
            "near_path_m": path_m,
            "far_path_m": path_m,
            "near_squares": squares_to_end,
            "far_squares": squares_to_end,
            "brace_label": brace_label,
            "brace_diameter_mm": math.sqrt(4.0 * brace_area_mm2 / math.pi) if brace_area_mm2 > 0.0 else 0.0,
            "brace_area_mm2": brace_area_mm2,
            "diagonal_length_mm": diagonal_length_mm,
            "base_spring_kn_mm": base_spring_kn_mm,
            "calibrated_base_spring_kn_mm": calibrated_base_spring_kn_mm,
            "calibration_factor": EAVE_BRACING_PATH_CALIBRATION_FACTOR,
            "one_end_spring_kn_mm": one_end_spring_kn_mm,
            "effective_spring_kn_mm": effective_spring_kn_mm,
        }

    def purlin_capacity_row(self, table, section, span_mm):
        for profile in table.get("profiles", []):
            if profile.get("section") != section:
                continue
            rows = profile.get("rows", [])
            if not rows:
                return None
            if span_mm <= rows[0].get("span_mm", 0.0):
                return dict(rows[0])
            if span_mm > rows[-1].get("span_mm", 0.0) + 1e-9:
                return None
            for lower, upper in zip(rows[:-1], rows[1:]):
                lower_span = lower.get("span_mm", 0.0)
                upper_span = upper.get("span_mm", 0.0)
                if lower_span <= span_mm <= upper_span + 1e-9:
                    if abs(upper_span - lower_span) <= 1e-9:
                        return dict(upper)
                    ratio = (span_mm - lower_span) / (upper_span - lower_span)
                    result = {"span_mm": span_mm, "interpolated": abs(span_mm - lower_span) > 1e-9 and abs(span_mm - upper_span) > 1e-9}
                    for key, lower_value in lower.items():
                        if key == "span_mm":
                            continue
                        upper_value = upper.get(key)
                        if isinstance(lower_value, (int, float)) and isinstance(upper_value, (int, float)):
                            result[key] = lower_value + (upper_value - lower_value) * ratio
                        elif key == "strength_by_bridging_kn_m" and isinstance(lower_value, dict) and isinstance(upper_value, dict):
                            values = {}
                            for bridge_key in sorted(set(lower_value).intersection(upper_value)):
                                values[bridge_key] = lower_value[bridge_key] + (upper_value[bridge_key] - lower_value[bridge_key]) * ratio
                            if values:
                                result[key] = values
                                result["strength_bridging"] = max(values, key=values.get)
                    return result
        return None

    def metroll_section_area_mm2(self, section):
        areas = {
            "C/Z 150 12": 354.0,
            "C/Z 150 15": 442.0,
            "C/Z 150 19": 561.0,
            "C/Z 150 24": 708.0,
            "C/Z 200 12": 444.0,
            "C/Z 200 15": 555.0,
            "C/Z 200 19": 713.0,
            "C/Z 200 24": 900.0,
            "C/Z 250 15": 638.0,
            "C/Z 250 19": 808.0,
            "C/Z 250 24": 1020.0,
            "C/Z 300 19": 998.0,
            "C/Z 300 24": 1260.0,
            "C/Z 300 30": 1575.0,
            "C/Z 350 19": 1207.0,
            "C/Z 350 24": 1524.0,
            "C/Z 350 30": 1905.0,
        }
        if section in areas:
            return areas[section]
        numbers = [float(value) for value in re.findall(r"\d+", section or "")]
        if len(numbers) >= 2:
            return numbers[0] * numbers[1] / 10.0
        return float("inf")

    def steel_weight_kg(self, area_mm2, length_mm):
        return area_mm2 * length_mm * 1e-9 * 7850.0

    def stock_length_m_for_cut(self, cut_length_m):
        if cut_length_m <= 0.0:
            return 0.0
        for stock_length in UB_STOCK_LENGTHS_M:
            if cut_length_m <= stock_length + 1e-9:
                return stock_length
        pieces = math.ceil(cut_length_m / UB_STOCK_LENGTHS_M[-1])
        return pieces * UB_STOCK_LENGTHS_M[-1]

    def section_cost_bucket(self, profile):
        return costing.section_cost_bucket(profile)
    def costing_physical_cut_lengths_m(self, structure):
        return costing.costing_physical_cut_lengths_m(structure)
    def metroll_section_weight_kg_m(self, section):
        area = self.metroll_section_area_mm2(section)
        if not math.isfinite(area):
            return 0.0
        return area * 1e-6 * 7850.0

    def metroll_section_dimensions(self, section):
        text = str(section or "").upper()
        numbers = [float(value) for value in re.findall(r"\d+", text)]
        depth_mm = numbers[0] if numbers else 150.0
        thickness_mm = (numbers[1] / 10.0) if len(numbers) >= 2 else 1.9
        flange_by_depth = {
            150: 57.0,
            200: 69.0,
            250: 69.0,
            300: 87.0,
            350: 113.0,
            400: 125.0,
        }
        depth_key = min(flange_by_depth, key=lambda value: abs(value - depth_mm))
        flange_mm = flange_by_depth[depth_key]
        return {
            "section": str(section or ""),
            "depth_mm": depth_mm,
            "flange_width_mm": flange_mm,
            "flange_under_mm": flange_mm,
            "thickness_mm": thickness_mm,
            "shape": "z" if "Z" in text and "C/Z" not in text else "c",
        }

    def costing_rate_from_input(self, widget, default_key):
        try:
            return max(float(widget.text()), 0.0)
        except ValueError:
            return float(COSTING_DEFAULTS[default_key])

    def foundation_float_from_input(self, widget, default):
        try:
            return max(float(widget.text()), 0.0)
        except ValueError:
            return default

    def design_pier_footing(self, compression_kn, uplift_kn, bearing_kpa, skin_friction_kpa, use_skin_friction_for_bearing=False):
        compression_kn = max(compression_kn, 0.0)
        uplift_kn = max(uplift_kn, 0.0)
        depth_step_m = 0.25
        for diameter_mm in STANDARD_PIER_DIAMETERS_MM:
            diameter_m = diameter_mm / 1000.0
            base_area_m2 = math.pi * diameter_m**2 / 4.0
            perimeter_m = math.pi * diameter_m
            depth_m = 1.0
            while depth_m <= 4.0 + 1e-9:
                skin_capacity_kn = skin_friction_kpa * perimeter_m * max(depth_m - 1.0, 0.0)
                bearing_skin_capacity_kn = skin_capacity_kn if use_skin_friction_for_bearing else 0.0
                bearing_capacity_kn = bearing_kpa * base_area_m2 + bearing_skin_capacity_kn
                if bearing_capacity_kn + 1e-9 < compression_kn:
                    depth_m += depth_step_m
                    continue
                skin_capacity_kn = skin_friction_kpa * perimeter_m * max(depth_m - 1.0, 0.0)
                if skin_capacity_kn + 1e-9 >= uplift_kn:
                    return {
                        "diameter_mm": diameter_mm,
                        "depth_m": depth_m,
                        "bearing_capacity_kn": bearing_capacity_kn,
                        "base_bearing_capacity_kn": bearing_kpa * base_area_m2,
                        "bearing_skin_capacity_kn": bearing_skin_capacity_kn,
                        "skin_capacity_kn": skin_capacity_kn,
                        "use_skin_friction_for_bearing": use_skin_friction_for_bearing,
                        "status": "OK",
                    }
                depth_m += depth_step_m

        diameter_mm = STANDARD_PIER_DIAMETERS_MM[-1]
        diameter_m = diameter_mm / 1000.0
        base_area_m2 = math.pi * diameter_m**2 / 4.0
        perimeter_m = math.pi * diameter_m
        required_skin_depth_m = 1.0
        if skin_friction_kpa * perimeter_m > 1e-9:
            required_skin_depth_m = 1.0 + uplift_kn / (skin_friction_kpa * perimeter_m)
        required_bearing_diameter_m = 0.0
        if bearing_kpa > 1e-9:
            required_bearing_diameter_m = math.sqrt(4.0 * compression_kn / (math.pi * bearing_kpa))
        depth_m = max(4.0, math.ceil(required_skin_depth_m / depth_step_m) * depth_step_m)
        skin_capacity_kn = skin_friction_kpa * perimeter_m * max(depth_m - 1.0, 0.0)
        bearing_skin_capacity_kn = skin_capacity_kn if use_skin_friction_for_bearing else 0.0
        return {
            "diameter_mm": diameter_mm,
            "depth_m": depth_m,
            "bearing_capacity_kn": bearing_kpa * base_area_m2 + bearing_skin_capacity_kn,
            "base_bearing_capacity_kn": bearing_kpa * base_area_m2,
            "bearing_skin_capacity_kn": bearing_skin_capacity_kn,
            "skin_capacity_kn": skin_capacity_kn,
            "required_bearing_diameter_mm": required_bearing_diameter_m * 1000.0,
            "use_skin_friction_for_bearing": use_skin_friction_for_bearing,
            "status": "CHECK" if required_bearing_diameter_m * 1000.0 > diameter_mm + 1e-9 else "OK >4m",
        }

    def foundation_design_from_reactions(self, structure, combinations, apply_combination_loads, foundation_nodes):
        bearing_kpa = self.foundation_float_from_input(self.foundation_bearing_input, 150.0)
        skin_friction_kpa = self.foundation_float_from_input(self.foundation_skin_friction_input, 15.0)
        use_skin_friction_for_bearing = self.foundation_skin_bearing_checkbox.isChecked()
        items = []
        for label, node in foundation_nodes:
            envelope = {
                "compression_kn": 0.0,
                "compression_combo": "-",
                "uplift_kn": 0.0,
                "uplift_combo": "-",
                "shear_kn": 0.0,
                "shear_combo": "-",
                "moment_knm": 0.0,
                "moment_combo": "-",
            }
            for combination in combinations:
                apply_combination_loads(combination)
                _, reactions, _, _ = self.solve_structure(structure)
                ry_kn = reactions[node.uy] / 1000.0
                rx_kn = reactions[node.ux] / 1000.0
                mz_knm = reactions[node.rz] / 1_000_000.0
                compression_kn = max(ry_kn, 0.0)
                uplift_kn = max(-ry_kn, 0.0)
                shear_kn = abs(rx_kn)
                moment_knm = abs(mz_knm)
                if combination.is_serviceability and compression_kn > envelope["compression_kn"]:
                    envelope["compression_kn"] = compression_kn
                    envelope["compression_combo"] = combination.name
                if combination.is_ultimate and uplift_kn > envelope["uplift_kn"]:
                    envelope["uplift_kn"] = uplift_kn
                    envelope["uplift_combo"] = combination.name
                if combination.is_ultimate and shear_kn > envelope["shear_kn"]:
                    envelope["shear_kn"] = shear_kn
                    envelope["shear_combo"] = combination.name
                if combination.is_ultimate and moment_knm > envelope["moment_knm"]:
                    envelope["moment_knm"] = moment_knm
                    envelope["moment_combo"] = combination.name
            design = self.design_pier_footing(
                envelope["compression_kn"],
                envelope["uplift_kn"],
                bearing_kpa,
                skin_friction_kpa,
                use_skin_friction_for_bearing,
            )
            items.append({"label": label, "node": node.id, **envelope, **design})
        return {
            "bearing_kpa": bearing_kpa,
            "skin_friction_kpa": skin_friction_kpa,
            "use_skin_friction_for_bearing": use_skin_friction_for_bearing,
            "diameters_mm": STANDARD_PIER_DIAMETERS_MM,
            "items": items,
        }

    def foundation_design_from_envelopes(self, reaction_envelopes):
        bearing_kpa = self.foundation_float_from_input(self.foundation_bearing_input, 150.0)
        skin_friction_kpa = self.foundation_float_from_input(self.foundation_skin_friction_input, 15.0)
        use_skin_friction_for_bearing = self.foundation_skin_bearing_checkbox.isChecked()
        items = []
        for envelope in reaction_envelopes:
            design = self.design_pier_footing(
                envelope.get("compression_kn", 0.0),
                envelope.get("uplift_kn", 0.0),
                bearing_kpa,
                skin_friction_kpa,
                use_skin_friction_for_bearing,
            )
            items.append({**envelope, **design})
        return {
            "bearing_kpa": bearing_kpa,
            "skin_friction_kpa": skin_friction_kpa,
            "use_skin_friction_for_bearing": use_skin_friction_for_bearing,
            "diameters_mm": STANDARD_PIER_DIAMETERS_MM,
            "items": items,
        }

    def costing_from_structure(self, structure, building_length_m, bay_size_m):
        costing_structure = copy.copy(structure)
        costing_structure.elements = [copy.copy(element) for element in structure.elements]
        self.apply_auto_web_assignments_to_structure(costing_structure)
        return costing.costing_from_structure(self, costing_structure, building_length_m, bay_size_m)
    def purlin_design_pressures(self, wind_inputs, tributary_area_m2=None, edge_zone=None, return_info=False, wind_pressure="ultimate"):
        max_upward_kpa = 0.0
        max_downward_kpa = 0.0
        max_local_pressure_factor = 1.0
        local_dimension_a_m = 0.0
        purlin_wind_inputs = replace(wind_inputs, left_canopy_length_m=0.0, right_canopy_length_m=0.0)
        for cpe_case in CPE_CASE_OPTIONS:
            source_direction = self.wind_source_direction_for_case(purlin_wind_inputs.orientation, cpe_case)
            result = calculate_wind(replace(purlin_wind_inputs, orientation=source_direction))
            pressure_scale = wind_pressure_scale(result, wind_pressure)
            roof_length = result.roof_slope_length_m
            result_a_m = local_pressure_dimension_a(result)
            local_dimension_a_m = max(local_dimension_a_m, result_a_m)
            edge_width = result_a_m
            for cpi_case in CPI_CASE_OPTIONS:
                cpi = active_cpi_for_case(result, cpi_case, cpe_case)
                cpi_pressure = cpi * result.wu_kn_m2 * pressure_scale * internal_pressure_factor(result, cpi)
                for zone in result.roof_zones:
                    zone_overlaps_edge = (
                        zone.distance_from_eave_from_m < edge_width
                        or zone.distance_from_eave_to_m > roof_length - edge_width
                    )
                    zone_overlaps_non_edge = (
                        zone.distance_from_eave_to_m > edge_width
                        and zone.distance_from_eave_from_m < roof_length - edge_width
                    )
                    if edge_zone is True and not zone_overlaps_edge:
                        continue
                    if edge_zone is False and not zone_overlaps_non_edge:
                        continue
                    proximity_m = min(
                        max(zone.distance_from_eave_from_m, 0.0),
                        max(roof_length - zone.distance_from_eave_to_m, 0.0),
                    )
                    local_pressure_factor = 1.0
                    if edge_zone is True and tributary_area_m2 is not None:
                        local_pressure_factor = roof_local_pressure_factor(result, tributary_area_m2, proximity_m)
                    max_local_pressure_factor = max(max_local_pressure_factor, local_pressure_factor)
                    if tributary_area_m2 is None:
                        external_pressures = [
                            zone.pressure_max_kn_m2 * pressure_scale,
                            zone.pressure_min_kn_m2 * pressure_scale,
                        ]
                    else:
                        external_factor = external_pressure_factor(result, "roof", tributary_area_m2)
                        external_pressures = [
                            (-zone.cpe_max) * result.wu_kn_m2 * pressure_scale * external_factor,
                            (-zone.cpe_min) * result.wu_kn_m2 * pressure_scale * external_factor,
                        ]
                    for external_pressure in external_pressures:
                        if external_pressure > 0.0:
                            external_pressure *= local_pressure_factor
                        combined_pressure = external_pressure + cpi_pressure
                        max_upward_kpa = max(max_upward_kpa, combined_pressure)
                        max_downward_kpa = max(max_downward_kpa, -combined_pressure)
        if return_info:
            return max_upward_kpa, max_downward_kpa, {
                "local_pressure_factor": max_local_pressure_factor,
                "local_dimension_a_m": local_dimension_a_m,
            }
        return max_upward_kpa, max_downward_kpa

    def wall_girt_design_pressures(self, wind_inputs, tributary_area_m2=None):
        max_outward_kpa = 0.0
        max_inward_kpa = 0.0
        max_inward_service_kpa = 0.0

        for cpe_case in CPE_CASE_OPTIONS:
            source_direction = self.wind_source_direction_for_case(wind_inputs.orientation, cpe_case)
            result = calculate_wind(replace(wind_inputs, orientation=source_direction))
            for cpi_case in CPI_CASE_OPTIONS:
                cpi = active_cpi_for_case(result, cpi_case, cpe_case)
                for cpe, surface in [(0.7, "windward_wall"), (result.leeward_wall_cpe, "leeward_wall")]:
                    for wind_pressure in ["ultimate", "serviceability"]:
                        design_area_m2 = tributary_area_m2
                        if design_area_m2 is None:
                            design_area_m2 = result.inputs.bay_size_m * result.inputs.eave_height_m
                        external_factor = external_pressure_factor(result, surface, max(float(design_area_m2), 0.01))
                        external = cpe * result.wu_kn_m2 * wind_pressure_scale(result, wind_pressure) * external_factor
                        internal = cpi * result.wu_kn_m2 * wind_pressure_scale(result, wind_pressure) * internal_pressure_factor(result, cpi)
                        combined = external - internal
                        if wind_pressure == "ultimate":
                            max_inward_kpa = max(max_inward_kpa, combined)
                            max_outward_kpa = max(max_outward_kpa, -combined)
                        else:
                            max_inward_service_kpa = max(max_inward_service_kpa, abs(combined))

        return max_outward_kpa, max_inward_kpa, max_inward_service_kpa

    def end_wall_bracing_design_pressures(self, wind_inputs):
        """Return the governing net end-wall pressures and their source cases."""
        pitch_rad = math.radians(abs(float(wind_inputs.roof_pitch_deg)))
        roof_rise_m = wind_inputs.building_width_m * math.tan(pitch_rad) * (0.5 if wind_inputs.roof_shape == "Gable" else 1.0)
        projected_area_m2 = wind_inputs.building_width_m * wind_inputs.eave_height_m + 0.5 * wind_inputs.building_width_m * roof_rise_m
        governing = {
            "ultimate_pressure_kpa": 0.0,
            "ultimate_case": "-",
            "service_pressure_kpa": 0.0,
            "service_case": "-",
        }
        for cpe_case in [case for case in CPE_CASE_OPTIONS if case.startswith("End")]:
            source_direction = self.wind_source_direction_for_case(wind_inputs.orientation, cpe_case)
            result = calculate_wind(replace(wind_inputs, orientation=source_direction))
            for cpi_case in CPI_CASE_OPTIONS:
                cpi = active_cpi_for_case(result, cpi_case, cpe_case)
                for surface_label, cpe, surface in (
                    ("windward end", 0.7, "windward_wall"),
                    ("leeward end", result.leeward_wall_cpe, "leeward_wall"),
                ):
                    external_factor = external_pressure_factor(result, surface, max(projected_area_m2, 0.01))
                    internal_factor = internal_pressure_factor(result, cpi)
                    for pressure_type, pressure_key, case_key in (
                        ("ultimate", "ultimate_pressure_kpa", "ultimate_case"),
                        ("serviceability", "service_pressure_kpa", "service_case"),
                    ):
                        scale = wind_pressure_scale(result, pressure_type)
                        net_pressure = abs(
                            cpe * result.wu_kn_m2 * scale * external_factor
                            - cpi * result.wu_kn_m2 * scale * internal_factor
                        )
                        if net_pressure > governing[pressure_key]:
                            governing[pressure_key] = net_pressure
                            governing[case_key] = f"{pressure_type.title()}: {cpe_case}, {cpi_case}, {surface_label}"
        return governing

    def calculate_longitudinal_bracing_design(self, wind_inputs, span_mm, eave_height_mm, pitch_deg, roof_shape, bay_size_m):
        if not self.longitudinal_bracing_enabled_checkbox.isChecked():
            self.longitudinal_bracing_design = None
            self.update_longitudinal_bracing_results()
            return

        pressure_cases = self.end_wall_bracing_design_pressures(wind_inputs)
        end_layout = mullion_layout(
            span_mm,
            eave_height_mm,
            pitch_deg,
            roof_shape,
            spacing_override_mm=self.end_wall_spacing_override_mm(),
        )
        panel_stations = [span_mm * index / end_layout["spaces"] for index in range(end_layout["spaces"] + 1)]
        if roof_shape == "Gable":
            panel_stations.append(span_mm / 2.0)
        panel_stations = sorted(set(panel_stations))
        roof_panel_areas_m2 = []
        roof_panel_widths_mm = []
        for x1, x2 in zip(panel_stations[:-1], panel_stations[1:]):
            h1 = roof_height_mm(x1, span_mm, eave_height_mm, pitch_deg, roof_shape)
            h2 = roof_height_mm(x2, span_mm, eave_height_mm, pitch_deg, roof_shape)
            roof_panel_areas_m2.append((x2 - x1) * (h1 + h2) / 2.0 / 1_000_000.0)
            roof_panel_widths_mm.append(x2 - x1)
        mullion_by_station = {
            round(float(item["station_mm"]), 6): item
            for item in end_layout.get("mullions", [])
        }
        roof_node_lines = []
        for station_mm in panel_stations:
            station_key = round(float(station_mm), 6)
            height_mm = roof_height_mm(station_mm, span_mm, eave_height_mm, pitch_deg, roof_shape)
            if abs(station_mm) <= 1e-6:
                line_type = "eave_strut"
                label = "Left eave strut" if roof_shape == "Gable" else "Low-eave strut"
            elif abs(station_mm - span_mm) <= 1e-6:
                line_type = "eave_strut"
                label = "Right eave strut" if roof_shape == "Gable" else "High-eave strut"
            elif station_key in mullion_by_station:
                mullion = mullion_by_station[station_key]
                line_type = "mullion_tie"
                label = f"Mullion tie M{mullion.get('index', len(roof_node_lines))}"
            else:
                line_type = "ridge_strut"
                label = "Ridge strut"
            roof_node_lines.append({
                "type": line_type,
                "label": label,
                "station_mm": station_mm,
                "height_mm": height_mm,
            })
        purlin_match = (self.purlin_check or {}).get("match", {}) or {}
        purlin_section = purlin_match.get("section") if purlin_match.get("status") == "OK" else None
        strut_candidates = []
        if purlin_section:
            area_mm2 = float(purlin_match.get("area_mm2") or self.metroll_section_area_mm2(purlin_section))
            i_min_mm4 = approximate_purlin_weak_axis_inertia_mm4(purlin_section, area_mm2)
            base = {"area_mm2": area_mm2, "i_min_mm4": i_min_mm4, "fy_mpa": 450.0}
            strut_candidates.extend([
                {**base, "label": f"Existing {purlin_section} purlin", "count": 1.0, "available_fraction": 0.5, "arrangement": "existing_purlin"},
                {**base, "label": f"Additional {purlin_section} purlin", "count": 1.0, "available_fraction": 1.0, "arrangement": "additional_purlin"},
                {**base, "label": f"Back-to-back {purlin_section} purlins", "count": 2.0, "available_fraction": 1.0, "arrangement": "back_to_back_purlins"},
            ])
        hollow_profiles = sorted(
            [*self.catalog.shs_profiles(), *self.catalog.rhs_profiles()],
            key=lambda profile: (profile.A, profile.name),
        )
        for profile in hollow_profiles:
            strut_candidates.append({
                "label": f"{profile.name} strut",
                "area_mm2": profile.A,
                "i_min_mm4": min(profile.Iyp, profile.Izp),
                "fy_mpa": profile.fy,
                "count": 1.0,
                "available_fraction": 1.0,
                "arrangement": "hollow_section",
            })

        roof_brace = self.selected_brace_size(self.roof_brace_size_combo)
        wall_brace = self.selected_brace_size(self.wall_brace_size_combo)
        self.longitudinal_bracing_design = calculate_preliminary_bracing(BracingInputs(
            span_mm=span_mm,
            eave_height_mm=eave_height_mm,
            roof_pitch_deg=pitch_deg,
            roof_shape=roof_shape,
            bay_width_mm=bay_size_m * 1000.0,
            roof_panel_widths_mm=tuple(roof_panel_widths_mm),
            roof_panel_projected_areas_m2=tuple(roof_panel_areas_m2),
            roof_node_lines=tuple(roof_node_lines),
            wall_side_count=2 if self.longitudinal_wall_sides_combo.currentText() == "Both sides" else 1,
            braced_bays_per_side=self.end_wall_braced_bay_count_input.value(),
            roof_brace_area_mm2=roof_brace["area_mm2"],
            roof_brace_label=roof_brace["label"],
            wall_brace_area_mm2=wall_brace["area_mm2"],
            wall_brace_label=wall_brace["label"],
            ultimate_pressure_kpa=pressure_cases["ultimate_pressure_kpa"],
            service_pressure_kpa=pressure_cases["service_pressure_kpa"],
            ultimate_case=pressure_cases["ultimate_case"],
            service_case=pressure_cases["service_case"],
            strut_candidates=tuple(strut_candidates),
        ))
        self.update_longitudinal_bracing_results()

    def match_metroll_purlin(self, span_type, span_mm, outward_kn_m, inward_strength_kn_m, inward_service_kn_m):
        if not self.metroll_tables:
            return {"status": "NOT CHECKED", "message": "Metroll capacity table cache not found."}
        table_ids = {
            "Single span": ("1A", "1B"),
            "Double span": ("2A", "2B"),
            "Continuous lapped": ("5A", "5B"),
        }.get(span_type)
        if table_ids is None:
            return {"status": "NOT CHECKED", "message": f"Unsupported purlin span type: {span_type}"}
        outward_table = self.metroll_tables["tables"].get(table_ids[0])
        inward_table = self.metroll_tables["tables"].get(table_ids[1])
        if not outward_table or not inward_table:
            return {"status": "NOT CHECKED", "message": f"Missing Metroll tables {table_ids[0]} / {table_ids[1]}."}
        first_profile = outward_table["profiles"][0]
        last_span = first_profile["rows"][-1]["span_mm"] if first_profile.get("rows") else 0.0
        if span_mm > last_span:
            return {"status": "NOT OK", "message": f"Bay span {span_mm:.0f} mm exceeds table maximum {last_span:.0f} mm."}

        passing = []
        candidates = []
        for outward_profile in outward_table.get("profiles", []):
            section = outward_profile.get("section")
            outward_row = self.purlin_capacity_row(outward_table, section, span_mm)
            inward_row = self.purlin_capacity_row(inward_table, section, span_mm)
            if not outward_row or not inward_row:
                continue
            outward_choice = self.bridged_strength_capacity(outward_row, section, span_mm, outward_kn_m)
            inward_choice = self.bridged_strength_capacity(inward_row, section, span_mm, inward_strength_kn_m)
            outward_capacity = outward_choice["capacity"]
            inward_strength_capacity = inward_choice["capacity"]
            inward_service_capacity = inward_row["service_l150_capacity_kn_m"]
            outward_bridging = outward_choice["label"]
            inward_bridging = inward_choice["label"]
            bridging_rows = max(outward_choice["rows"], inward_choice["rows"])
            minimum_bridging_rows = max(outward_choice["minimum_rows"], inward_choice["minimum_rows"])
            max_bridging_spacing_mm = max(outward_choice["max_spacing_mm"], inward_choice["max_spacing_mm"])
            max_bridged_bay_mm = max_bridging_spacing_mm * (bridging_rows + 1) if max_bridging_spacing_mm > 0.0 else 0.0
            capped_by_double = False
            if span_type == "Single span":
                double_outward_row = self.purlin_capacity_row(self.metroll_tables["tables"].get("2A", {}), section, span_mm)
                double_inward_row = self.purlin_capacity_row(self.metroll_tables["tables"].get("2B", {}), section, span_mm)
                if double_outward_row:
                    double_outward_choice = self.bridged_strength_capacity(double_outward_row, section, span_mm, outward_kn_m)
                    capped_by_double = capped_by_double or double_outward_choice["capacity"] < outward_capacity
                    if double_outward_choice["capacity"] < outward_capacity:
                        outward_bridging = double_outward_choice["label"]
                        bridging_rows = max(bridging_rows, double_outward_choice["rows"])
                    outward_capacity = min(outward_capacity, double_outward_choice["capacity"])
                if double_inward_row:
                    double_inward_choice = self.bridged_strength_capacity(double_inward_row, section, span_mm, inward_strength_kn_m)
                    capped_by_double = capped_by_double or double_inward_choice["capacity"] < inward_strength_capacity
                    capped_by_double = capped_by_double or double_inward_row["service_l150_capacity_kn_m"] < inward_service_capacity
                    if double_inward_choice["capacity"] < inward_strength_capacity:
                        inward_bridging = double_inward_choice["label"]
                        bridging_rows = max(bridging_rows, double_inward_choice["rows"])
                    inward_strength_capacity = min(inward_strength_capacity, double_inward_choice["capacity"])
                    inward_service_capacity = min(inward_service_capacity, double_inward_row["service_l150_capacity_kn_m"])
                max_bridged_bay_mm = max_bridging_spacing_mm * (bridging_rows + 1) if max_bridging_spacing_mm > 0.0 else 0.0
            section_numbers = [float(value) for value in re.findall(r"\d+", section or "")]
            depth_mm = section_numbers[0] if section_numbers else 0.0
            thickness_tenths_mm = section_numbers[1] if len(section_numbers) > 1 else float("inf")
            candidate = {
                "section": section,
                "area_mm2": self.metroll_section_area_mm2(section),
                "depth_mm": depth_mm,
                "thickness_tenths_mm": thickness_tenths_mm,
                "span_row_mm": outward_row["span_mm"],
                "outward_capacity_kn_m": outward_capacity,
                "inward_strength_capacity_kn_m": inward_strength_capacity,
                "inward_service_capacity_kn_m": inward_service_capacity,
                "outward_bridging": outward_bridging,
                "inward_bridging": inward_bridging,
                "bridging_rows": bridging_rows,
                "minimum_bridging_rows": minimum_bridging_rows,
                "max_bridging_spacing_mm": max_bridging_spacing_mm,
                "max_bridged_bay_mm": max_bridged_bay_mm,
                "capped_by_double_span": capped_by_double,
                "outward_ratio": outward_kn_m / outward_capacity if outward_capacity > 1e-12 else float("inf"),
                "inward_strength_ratio": inward_strength_kn_m / inward_strength_capacity if inward_strength_capacity > 1e-12 else float("inf"),
                "inward_service_ratio": inward_service_kn_m / inward_service_capacity if inward_service_capacity > 1e-12 else float("inf"),
            }
            candidates.append(candidate)
            if (
                outward_kn_m <= outward_capacity + 1e-9
                and inward_strength_kn_m <= inward_strength_capacity + 1e-9
                and inward_service_kn_m <= inward_service_capacity + 1e-9
            ):
                passing.append({
                    "status": "OK",
                    "section": section,
                    "area_mm2": self.metroll_section_area_mm2(section),
                    "depth_mm": depth_mm,
                    "thickness_tenths_mm": thickness_tenths_mm,
                    "span_row_mm": outward_row["span_mm"],
                    "interpolated": outward_row.get("interpolated", False) or inward_row.get("interpolated", False),
                    "tables": f"{table_ids[0]} / {table_ids[1]}",
                    "outward_capacity_kn_m": outward_capacity,
                    "inward_strength_capacity_kn_m": inward_strength_capacity,
                    "inward_service_capacity_kn_m": inward_service_capacity,
                    "outward_bridging": outward_bridging,
                    "inward_bridging": inward_bridging,
                    "bridging_rows": bridging_rows,
                    "minimum_bridging_rows": minimum_bridging_rows,
                    "max_bridging_spacing_mm": max_bridging_spacing_mm,
                    "max_bridged_bay_mm": max_bridged_bay_mm,
                    "capped_by_double_span": capped_by_double,
                })
        if passing:
            lightest_area = min(item["area_mm2"] for item in passing)
            near_lightest = [
                item for item in passing
                if item["area_mm2"] <= lightest_area * 1.05
            ]
            selected = min(near_lightest, key=lambda item: (-item["depth_mm"], item["area_mm2"], item["section"]))
            failed = [
                item for item in candidates
                if max(item["outward_ratio"], item["inward_strength_ratio"], item["inward_service_ratio"]) > 1.0
            ]
            failed.sort(key=lambda item: max(item["outward_ratio"], item["inward_strength_ratio"], item["inward_service_ratio"]))
            selected["near_misses"] = failed[:3]
            return selected
        return {"status": "NOT OK", "message": "No listed Metroll section satisfies the calculated line loads."}

    def purlin_check_from_inputs(self, purlin_layout, bay_size_m, roof_loads, wind_inputs, span_type):
        if purlin_layout is None or purlin_layout.max_spacing_mm <= 0.0 or bay_size_m <= 0.0:
            return None
        spacing_m = purlin_layout.max_spacing_mm / 1000.0
        span_mm = bay_size_m * 1000.0
        local_area_m2 = spacing_m * bay_size_m
        local_dimension_a_m = local_pressure_dimension_a(wind_inputs)
        edge_rows = max(1, math.ceil(local_dimension_a_m / spacing_m))
        permanent_kpa = abs(roof_loads.permanent_vertical_kpa)
        live_kpa = abs(roof_loads.q_vertical_kpa)
        inward_gravity_uls_kpa = 1.2 * permanent_kpa + 1.5 * live_kpa
        wind_upward_kpa, wind_downward_kpa = self.purlin_design_pressures(wind_inputs, edge_zone=False)
        wind_service_upward_kpa, wind_service_downward_kpa = self.purlin_design_pressures(
            wind_inputs,
            edge_zone=False,
            wind_pressure="serviceability",
        )
        outward_kn_m = wind_upward_kpa * spacing_m
        inward_wind_uls_kpa = 1.2 * permanent_kpa + wind_downward_kpa
        inward_strength_kn_m = max(inward_gravity_uls_kpa, inward_wind_uls_kpa) * spacing_m
        inward_service_kpa = max(wind_service_upward_kpa, wind_service_downward_kpa)
        inward_service_kn_m = inward_service_kpa * spacing_m
        match = self.match_metroll_purlin(span_type, span_mm, outward_kn_m, inward_strength_kn_m, inward_service_kn_m)
        local_wind_upward_kpa, local_wind_downward_kpa, local_pressure_info = self.purlin_design_pressures(
            wind_inputs,
            tributary_area_m2=local_area_m2,
            edge_zone=True,
            return_info=True,
        )
        local_wind_service_upward_kpa, local_wind_service_downward_kpa = self.purlin_design_pressures(
            wind_inputs,
            tributary_area_m2=local_area_m2,
            edge_zone=True,
            wind_pressure="serviceability",
        )
        local_outward_kn_m = local_wind_upward_kpa * spacing_m
        local_inward_wind_uls_kpa = 1.2 * permanent_kpa + local_wind_downward_kpa
        local_inward_strength_kn_m = max(inward_gravity_uls_kpa, local_inward_wind_uls_kpa) * spacing_m
        local_inward_service_kpa = max(local_wind_service_upward_kpa, local_wind_service_downward_kpa)
        local_inward_service_kn_m = local_inward_service_kpa * spacing_m
        local_match = self.match_metroll_purlin(span_type, span_mm, local_outward_kn_m, local_inward_strength_kn_m, local_inward_service_kn_m)
        return {
            "span_type": span_type,
            "spacing_mm": purlin_layout.max_spacing_mm,
            "purlin_rows": len(purlin_layout.points),
            "extra_rows_per_slope": int(getattr(self, "extra_purlin_rows", 0)),
            "span_mm": span_mm,
            "local_area_m2": local_area_m2,
            "edge_rows": edge_rows,
            "permanent_kpa": permanent_kpa,
            "live_kpa": live_kpa,
            "wind_upward_kpa": wind_upward_kpa,
            "wind_downward_kpa": wind_downward_kpa,
            "wind_service_upward_kpa": wind_service_upward_kpa,
            "wind_service_downward_kpa": wind_service_downward_kpa,
            "outward_kn_m": outward_kn_m,
            "inward_strength_kn_m": inward_strength_kn_m,
            "inward_gravity_uls_kpa": inward_gravity_uls_kpa,
            "inward_wind_uls_kpa": inward_wind_uls_kpa,
            "inward_service_kn_m": inward_service_kn_m,
            "match": match,
            "local_wind_upward_kpa": local_wind_upward_kpa,
            "local_wind_downward_kpa": local_wind_downward_kpa,
            "local_wind_service_upward_kpa": local_wind_service_upward_kpa,
            "local_wind_service_downward_kpa": local_wind_service_downward_kpa,
            "local_outward_kn_m": local_outward_kn_m,
            "local_inward_strength_kn_m": local_inward_strength_kn_m,
            "local_inward_service_kn_m": local_inward_service_kn_m,
            "local_pressure_factor": local_pressure_info["local_pressure_factor"],
            "local_dimension_a_m": local_pressure_info["local_dimension_a_m"],
            "local_inward_wind_uls_kpa": local_inward_wind_uls_kpa,
            "local_match": local_match,
        }

    def wall_girt_check_from_inputs(self, wind_inputs, bay_size_m, eave_height_mm, span_type):
        if bay_size_m <= 0.0:
            return None
        spacing_mm = self.actual_wall_girt_spacing_mm(eave_height_mm, wind_inputs.wind_region)
        spacing_m = spacing_mm / 1000.0
        span_mm = bay_size_m * 1000.0
        wind_outward_kpa, wind_inward_kpa, wind_service_kpa = self.wall_girt_design_pressures(wind_inputs)
        outward_kn_m = wind_outward_kpa * spacing_m
        inward_strength_kn_m = wind_inward_kpa * spacing_m
        inward_service_kn_m = wind_service_kpa * spacing_m
        match = self.match_metroll_purlin(span_type, span_mm, outward_kn_m, inward_strength_kn_m, inward_service_kn_m)
        return {
            "span_type": span_type,
            "spacing_mm": spacing_mm,
            "max_spacing_mm": self.wall_girt_spacing_mm(wind_inputs.wind_region),
            "span_mm": span_mm,
            "wind_outward_kpa": wind_outward_kpa,
            "wind_inward_kpa": wind_inward_kpa,
            "wind_service_kpa": wind_service_kpa,
            "outward_kn_m": outward_kn_m,
            "inward_strength_kn_m": inward_strength_kn_m,
            "inward_service_kn_m": inward_service_kn_m,
            "match": match,
        }

    def end_wall_spacing_override_mm(self):
        widget = getattr(self, "end_wall_mullion_spacing_override_input", None)
        text = widget.text().strip() if widget is not None else ""
        if not text:
            return None
        value = mm_from_metres_text(text)
        if value <= 0.0:
            raise ValueError("end-wall mullion spacing override must be greater than zero")
        return value

    def calculate_end_wall_design(self, wind_inputs, span_mm, eave_height_mm, pitch_deg, roof_shape):
        end_wall_count = int(bool(wind_inputs.front_wall_clad)) + int(bool(wind_inputs.back_wall_clad))
        spacing_override_mm = self.end_wall_spacing_override_mm()
        preliminary_layout = mullion_layout(
            span_mm,
            eave_height_mm,
            pitch_deg,
            roof_shape,
            spacing_override_mm=spacing_override_mm,
        )
        governing_height_mm = max(
            (item["height_mm"] for item in preliminary_layout["mullions"]),
            default=eave_height_mm,
        )
        mullion_tributary_area_m2 = (
            preliminary_layout["actual_spacing_mm"] * governing_height_mm / 1_000_000.0
        )
        outward_kpa, inward_kpa, service_kpa = self.wall_girt_design_pressures(
            wind_inputs,
            tributary_area_m2=mullion_tributary_area_m2,
        )
        self.end_wall_mullion_design = design_end_wall_mullions(
            span_mm=span_mm,
            eave_height_mm=eave_height_mm,
            pitch_deg=pitch_deg,
            roof_shape=roof_shape,
            outward_uls_kpa=outward_kpa,
            inward_uls_kpa=inward_kpa,
            service_kpa=service_kpa,
            profiles=self.catalog.end_wall_mullion_profiles(),
            spacing_override_mm=spacing_override_mm,
            end_wall_count=end_wall_count,
        )
        if end_wall_count > 0:
            self.end_wall_girt_check = self.wall_girt_check_from_inputs(
                wind_inputs,
                self.end_wall_mullion_design["actual_spacing_mm"] / 1000.0,
                eave_height_mm,
                self.wall_girt_span_type_combo.currentText(),
            )
        else:
            self.end_wall_girt_check = None
        self.update_end_wall_results()

    def update_end_wall_results(self):
        design = self.end_wall_mullion_design or {}
        girt = self.end_wall_girt_check or {}
        if not design:
            self.end_wall_layout_label.setText("Not checked")
            self.end_wall_mullion_check_label.setText("Not checked")
            self.end_wall_girt_check_label.setText("Not checked")
            return

        end_count = int(design.get("end_wall_count", 0) or 0)
        if end_count <= 0:
            self.end_wall_layout_label.setText("No clad front or back end wall selected.")
            self.end_wall_mullion_check_label.setText("NOT REQUIRED - end walls open")
            self.end_wall_girt_check_label.setText("NOT REQUIRED - end walls open")
            self.end_wall_layout_label.setStyleSheet("font-weight: bold;")
            self.end_wall_mullion_check_label.setStyleSheet("font-weight: bold;")
            self.end_wall_girt_check_label.setStyleSheet("font-weight: bold;")
            return

        override = design.get("spacing_override_mm")
        mode_suffix = f" (manual target {override / 1000.0:.3f} m)" if override else ""
        self.end_wall_layout_label.setText(
            f"{design.get('spaces', 0)} equal spaces @ {design.get('actual_spacing_mm', 0.0) / 1000.0:.3f} m; "
            f"{design.get('mullion_count', 0)} intermediate mullion(s) per clad end{mode_suffix}."
        )
        override_warning = bool(override and override > design.get("automatic_max_spacing_mm", 8000.0) + 1e-9)
        self.end_wall_layout_label.setStyleSheet(
            f"font-weight: bold; color: {'#b42318' if override_warning else '#1b7f3a'};"
        )
        mullion_status = design.get("status", "NOT CHECKED")
        selected = design.get("selected") or {}
        mullion_ok = mullion_status in {"OK", "NOT REQUIRED"}
        if selected:
            self.end_wall_mullion_check_label.setText(
                f"{mullion_status} - {selected.get('section', '-')} | strength {selected.get('strength_ratio', float('inf')):.3f}, "
                f"deflection {selected.get('deflection_ratio', float('inf')):.3f}"
            )
        else:
            self.end_wall_mullion_check_label.setText(
                f"{mullion_status} - {design.get('message', 'No intermediate mullion section required')}"
            )
        self.end_wall_mullion_check_label.setStyleSheet(
            f"font-weight: bold; color: {'#1b7f3a' if mullion_ok else '#b42318'};"
        )

        girt_match = girt.get("match", {})
        girt_status = girt_match.get("status", "NOT CHECKED")
        if girt_status == "OK":
            self.end_wall_girt_check_label.setText(
                f"OK - {self.metroll_section_display(girt_match.get('section', '-'), girt.get('span_type', ''))} "
                f"@ {girt.get('spacing_mm', 0.0):.0f} mm vertical, "
                f"{girt.get('span_mm', 0.0):.0f} mm span"
            )
        else:
            self.end_wall_girt_check_label.setText(f"{girt_status} - {girt_match.get('message', 'No match')}")
        self.end_wall_girt_check_label.setStyleSheet(
            f"font-weight: bold; color: {'#1b7f3a' if girt_status == 'OK' else '#b42318'};"
        )

    def update_longitudinal_bracing_results(self):
        if getattr(self, "longitudinal_bracing_status_label", None) is None:
            return
        design = getattr(self, "longitudinal_bracing_design", None) or {}
        if not self.longitudinal_bracing_enabled_checkbox.isChecked():
            self.longitudinal_bracing_status_label.setText("Disabled")
            self.longitudinal_bracing_status_label.setStyleSheet("font-weight: bold;")
            self.longitudinal_bracing_case_label.setText("No governing end-wind case calculated.")
            self.roof_bracing_load_label.setText("Not calculated")
            self.wall_bracing_load_label.setText("Not calculated")
            self.bracing_strut_result_label.setText(
                "Automatic hierarchy: existing purlin, additional purlin, back-to-back purlins, then SHS/RHS."
            )
            return
        if not design:
            self.longitudinal_bracing_status_label.setText("Enabled - click Generate & Solve.")
            self.longitudinal_bracing_status_label.setStyleSheet("font-weight: bold; color: #9a6700;")
            return
        status = design.get("status", "NOT CHECKED")
        ratio = design.get("governing_capacity_ratio", float("inf"))
        self.longitudinal_bracing_status_label.setText(
            f"{status} - governing utilization {ratio:.3f}"
        )
        self.longitudinal_bracing_status_label.setStyleSheet(
            f"font-weight: bold; color: {'#1b7f3a' if status == 'OK' else '#b42318'};"
        )
        self.longitudinal_bracing_case_label.setText(
            f"{design.get('ultimate_case', '-')} | end-wall resultant {design.get('ultimate_resultant_kn', 0.0):.2f} kN | "
            f"roof reaction {design.get('roof_reaction_uls_kn', 0.0):.2f} kN"
        )
        roof = design.get("roof_uls", {})
        wall = design.get("wall_uls", {})
        self.roof_bracing_load_label.setText(
            f"{design.get('roof_brace_label', '-')} | N* {roof.get('brace_force_kn', 0.0):.2f} kN | "
            f"capacity {roof.get('capacity_kn', 0.0):.2f} kN | utilization {roof.get('capacity_ratio', 0.0):.3f}"
        )
        self.wall_bracing_load_label.setText(
            f"{design.get('wall_brace_label', '-')} | N* {wall.get('brace_force_kn', 0.0):.2f} kN | "
            f"capacity {wall.get('capacity_kn', 0.0):.2f} kN | utilization {wall.get('capacity_ratio', 0.0):.3f}"
        )
        strut_lines = []
        for heading, key in (
            ("Eave struts", "eave_struts"),
            ("Mullion ties", "mullion_ties"),
            ("Ridge struts", "ridge_struts"),
        ):
            items = design.get(key, []) or []
            if not items:
                continue
            strut_lines.append(f"{heading}:")
            for item in items:
                selection = item.get("selection", {})
                strut_lines.append(
                    f"- {item.get('label', '-')} @ x={item.get('station_mm', 0.0) / 1000.0:.3f} m: "
                    f"N* {item.get('demand_kn', 0.0):.2f} kN | {selection.get('label', '-')} | "
                    f"capacity {selection.get('capacity_kn', 0.0):.2f} kN | utilization {selection.get('ratio', 0.0):.3f}"
                )
        self.bracing_strut_result_label.setText("\n".join(strut_lines) if strut_lines else "No strut lines calculated.")

    def wind_inputs_from_ui(self, span_mm, pitch_deg, eave_mm):
        building_length_m = float(self.building_length_input.text())
        wall_states = self.envelope_plan_selector.wall_states()
        frame_type = self.frame_type_from_wall_states(wall_states)
        return WindInputs(
            wind_region=self.wind_region_combo.currentText(),
            importance_level=int(self.importance_combo.currentText()),
            terrain_category=float(self.terrain_combo.currentText()),
            eave_height_m=eave_mm / 1000.0,
            roof_pitch_deg=pitch_deg,
            roof_shape=self.current_roof_shape(),
            building_width_m=span_mm / 1000.0,
            building_length_m=building_length_m,
            bay_size_m=self.bay_size_m_from_ui(),
            orientation=self.wind_orientation_selector.currentText(),
            frame_type=frame_type,
            cpi_case="Cpi +",
            left_wall_clad=wall_states["left"],
            right_wall_clad=wall_states["right"],
            front_wall_clad=wall_states["front"],
            back_wall_clad=wall_states["back"],
            left_canopy_length_m=(max(float(self.left_canopy_length_input.text()), 0.0) if self.side_addition_selected(self.left_canopy_type_combo) else 0.0),
            right_canopy_length_m=(max(float(self.right_canopy_length_input.text()), 0.0) if self.side_addition_selected(self.right_canopy_type_combo) else 0.0),
            reduction_factor=float(self.wind_reduction_input.text()),
            internal_pressure_mode=self.internal_pressure_combo.currentText(),
        )

    def wind_source_direction_for_case(self, north_up_direction, cpe_case):
        directions = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"]
        if north_up_direction == "Any":
            return "Any"
        from wind import direction_bearing_degrees
        north_angle = direction_bearing_degrees(north_up_direction)

        def compass_direction_for_screen_direction(screen_direction):
            bearing = (direction_bearing_degrees(screen_direction) - north_angle) % 360
            if north_up_direction in directions:
                return directions[int(round(bearing / 45)) % 8]
            return bearing

        if str(cpe_case).startswith("Left"):
            return compass_direction_for_screen_direction("W")
        if str(cpe_case).startswith("Right"):
            return compass_direction_for_screen_direction("E")
        if str(cpe_case).startswith("End"):
            direction = compass_direction_for_screen_direction("N")
            walls = self.envelope_plan_selector.wall_states()
            if walls["front"] and walls["back"]:
                from wind import symmetric_end_source_direction
                return symmetric_end_source_direction(self.wind_region_combo.currentText(), direction)
            return direction
        return north_up_direction

    def midspan_deflection_divisor(self):
        key = "truss_combined_il1" if (self.serviceability_importance_level or 1) == 1 else "truss_combined_standard"
        return self.serviceability_limit_value(key)

    def midspan_component_deflection_divisors(self):
        if (self.serviceability_importance_level or 1) == 1:
            return {
                "G": self.serviceability_limit_value("truss_g_il1"),
                "Q": self.serviceability_limit_value("truss_q_il1"),
                "Ws": self.serviceability_limit_value("truss_ws_il1"),
            }
        return {
            "G": self.serviceability_limit_value("truss_g_standard"),
            "Q": self.serviceability_limit_value("truss_q_standard"),
            "Ws": self.serviceability_limit_value("truss_ws_standard"),
        }

    @staticmethod
    def governing_midspan_deflection_components():
        """Components that must be satisfied by member stiffness rather than precamber."""
        return ("Q", "Ws")

    @staticmethod
    def minimum_precamber_required_mm(demand_mm, limit_mm):
        """Minimum upward offset needed to bring permanent-load sag back to its limit."""
        return max(float(demand_mm) - max(float(limit_mm), 0.0), 0.0)

    def midspan_component_deflection_check(self, component, demand_mm, span_mm, divisor, item=None):
        """Classify one component as governing stiffness or permanent-load advisory."""
        limit = span_mm / divisor if span_mm > 0.0 else 0.0
        demand = max(float(demand_mm), 0.0)
        ratio = demand / limit if limit > 1e-12 else float("inf")
        governing = component in self.governing_midspan_deflection_components()
        precamber_required = self.minimum_precamber_required_mm(demand, limit) if component == "G" else 0.0
        if component == "G":
            status = "PRECAMBER REQUIRED" if precamber_required > 1e-9 else "WITHIN LIMIT"
        else:
            status = "OK" if ratio <= 1.0 else "NOT OK"
        return {
            "demand": demand,
            "limit": limit,
            "ratio": ratio,
            "status": status,
            "divisor": divisor,
            "item": item or {},
            "component": component,
            "governing": governing,
            "precamber_required_mm": precamber_required,
        }

    def column_deflection_divisor(self, include_crane_limit=False):
        if include_crane_limit and getattr(self, "serviceability_crane_active", False):
            return self.serviceability_limit_value("crane_rail_height")
        key = "column_il1" if (self.serviceability_importance_level or 1) == 1 else "column_standard"
        return self.serviceability_limit_value(key)

    def eave_deflection_divisor(self):
        override = getattr(self, "eave_deflection_limit_override", None)
        if override is not None and override > 0.0:
            return float(override)
        if getattr(self, "storage_enabled_checkbox", None) is not None and self.storage_enabled_checkbox.isChecked():
            return self.serviceability_limit_value("storage_eave")
        return self.column_deflection_divisor()

    def canopy_tip_deflection_divisor(self):
        key = "canopy_tip_il1" if (self.serviceability_importance_level or 1) == 1 else "canopy_tip_standard"
        return self.serviceability_limit_value(key)

    def column_half_width_for_span_offset(self, profile):
        return (profile.depth or profile.flange_width or 0.0) / 2.0

    def update_storage_section_visibility(self):
        group = getattr(self, "storage_section_group", None)
        if group is None:
            return
        enabled = bool(getattr(self, "storage_enabled_checkbox", None) and self.storage_enabled_checkbox.isChecked())
        group.setVisible(enabled)

    def update_license_status_label(self, refresh_server=False):
        label = getattr(self, "license_status_label", None)
        if label is None:
            return
        from licensing import license_enforced

        if not license_enforced():
            label.setText("Not enforced for this run")
            label.setStyleSheet("color: #777;")
            return
        try:
            from licensing import LicenseManager

            manager = LicenseManager()
            status = manager.refresh() if refresh_server else manager.local_status()
        except Exception as exc:
            label.setText(f"Check failed: {exc}")
            label.setStyleSheet("color: #b00020;")
            return
        if status.valid:
            details = []
            if status.customer:
                details.append(status.customer)
            if status.plan:
                details.append(status.plan)
            if status.days_remaining is not None:
                details.append(f"{status.days_remaining} days remaining")
            if status.warning:
                details.append(status.warning)
            suffix = f" ({', '.join(details)})" if details else ""
            label.setText(f"Valid{suffix}")
            color = "#9a6700" if status.warning else "#1b7f3a"
            label.setStyleSheet(f"color: {color}; font-weight: bold;")
        else:
            label.setText(status.reason)
            label.setStyleSheet("color: #b00020; font-weight: bold;")

    def update_web_section_visibility(self):
        rows = []
        rows.extend(getattr(self, "web_section_rows", []))
        rows.extend(getattr(self, "web_check_rows", []))
        rows.extend(getattr(self, "left_canopy_web_section_rows", []))
        rows.extend(getattr(self, "left_canopy_web_check_rows", []))
        rows.extend(getattr(self, "right_canopy_web_section_rows", []))
        rows.extend(getattr(self, "right_canopy_web_check_rows", []))
        for widget in rows:
            if widget is not None:
                widget.setVisible(False)

    def update_internal_column_visibility(self):
        has_internal_columns = self.internal_column_count_combo.currentText() != "None"
